const puppeteer = require('puppeteer');
const path = require('path');

(async () => {
  const browser = await puppeteer.launch({
    args: ['--no-sandbox', '--disable-setuid-sandbox']
  });
  const page = await browser.newPage();

  // A0 size at 72 dpi is roughly 2384 x 3370 pixels
  await page.setViewport({
    width: 2384,
    height: 3370,
    deviceScaleFactor: 2, // High resolution
  });

  const htmlPath = `file://${path.resolve('/app/output/poster.html')}`;
  await page.goto(htmlPath, { waitUntil: 'networkidle0' });

  await page.pdf({
    path: '/app/output/final_poster.pdf',
    width: '2384px',
    height: '3370px',
    printBackground: true
  });

  await page.screenshot({
    path: '/app/output/final_poster.png',
    fullPage: true
  });

  await browser.close();
  console.log("Poster rendered successfully.");
})();

